pub fn paint(ui: &egui::Ui, name: &str, rect: Rect) {
    egui::Image::new(source(name))
        .fit_to_exact_size(rect.size())
        .paint_at(ui, rect);
}
pub fn button(ui: &mut egui::Ui, name: &str, label: &str, size: Vec2, vertical: bool) -> Response {
    let response = ui.add_sized(
        size,
        egui::Button::new("")
            .fill(Color32::TRANSPARENT)
            .stroke(egui::Stroke::NONE)
            .corner_radius(5.),
    );
    let r = response.rect;
    let font = egui::FontId::proportional(if vertical { 12.5 } else { 14. });
    let text_height = ui
        .painter()
        .layout_no_wrap(
            label.to_owned(),
            font.clone(),
            Color32::from_rgb(16, 30, 66),
        )
        .size()
        .y;
    let top = if vertical {
        r.top()
            .min(ui.clip_rect().bottom() - 34. - text_height - 4.)
    } else {
        r.top()
    };
    let (icon_rect, text_at) = if vertical {
        (
            Rect::from_center_size(Pos2::new(r.center().x, top + 16.), Vec2::splat(28.)),
            Pos2::new(r.center().x, top + 34.),
        )
    } else {
        (
            Rect::from_center_size(Pos2::new(r.left() + 20., r.center().y), Vec2::splat(25.)),
            Pos2::new(r.left() + 43., r.center().y),
        )
    };
    paint(ui, name, icon_rect);
    ui.painter().text(
        text_at,
        if vertical {
            egui::Align2::CENTER_TOP
        } else {
            egui::Align2::LEFT_CENTER
        },
        label,
        font,
        Color32::from_rgb(16, 30, 66),
    );
    response.widget_info(|| {
        egui::WidgetInfo::labeled(egui::WidgetType::Button, ui.is_enabled(), label)
    });
    focus(ui, &response);
    response
}
pub fn focus(ui: &egui::Ui, r: &Response) {
    if r.has_focus() {
        ui.painter().rect_stroke(
            r.rect.shrink(1.),
            5.,
            egui::Stroke::new(2.2, Color32::from_rgb(7, 87, 237)),
            egui::StrokeKind::Inside,
        );
    }
}
